"""Offline JLPT N5 course with explanations, pronunciation and practice."""

from __future__ import annotations

from . import kana

LESSONS = [
    {"id":"01","title":"Хирагана и фонетика","kind":"kana","goal":"Научиться читать пять базовых гласных и понимать ритм японской речи.","text":"Хирагана — не алфавит в привычном смысле, а набор мор. Каждая мора занимает примерно один ритмический шаг: か это ka, а не k + a. Базовые гласные произносятся коротко и чисто: あ a, い i, う u, え e, お o. В японском нет русского ударения: высота тона зависит от слова, поэтому не пытайтесь выделять один слог силой.","grammar":"Знаки строки か читаются ka, ki, ku, ke, ko. Маленькая っ удваивает следующий согласный: がっこう gakkou. ん — отдельная мора: こんにちは kon-ni-chi-wa.","syntax":"Пока не строим предложения: сначала научитесь соединять мору в ровную последовательность без пауз внутри слова.","practice":"あいうえお\nかきくけこ\nがっこう — школа\nありがとうございます — большое спасибо","pronunciation":"a i u e o · ka ki ku ke ko · gakkou · arigatou gozaimasu","quiz":[("Как читается っ в がっこう?","Удваивает следующий согласный"),("Что означает ん?","Отдельная мора n")],"links":[("Tofugu: Hiragana","https://www.tofugu.com/japanese/learn-hiragana/"),("NHK: pronunciation","https://www.nhk.or.jp/lesson/english/learn/list/1.html")]},
    {"id":"02","title":"Катакана и долгие гласные","kind":"kana","goal":"Читать заимствованные слова и распознавать долгий звук.","text":"Катакана используется для иностранных слов, имён, брендов и звуков. Например, コーヒー koohii — кофе, カメラ kamera — камера. Знак ー удлиняет предыдущую гласную на одну мору: コー koо.","grammar":"В катакане ー важен для смысла: ビル biru — здание, ビール biiru — пиво. Маленькие ャュョ образуют сочетания: シャ sha, チョ cho.","syntax":"Заимствования сохраняют японскую слоговую структуру: strike превращается в ストライク sutoraiku.","practice":"アイウエオ / カキクケコ\nコーヒー — кофе\nスーパー — супермаркет\nゲーム — игра","pronunciation":"koohii · suupaa · geemu · kamera","quiz":[("Что делает ー?","Удлиняет предыдущую гласную"),("Как читается シャ?","sha")],"links":[("Tofugu: Katakana","https://www.tofugu.com/japanese/learn-katakana/")]},
    {"id":"03","title":"Частицы и порядок слов","kind":"grammar","goal":"Понимать тему, объект и сказуемое в простом предложении.","text":"Базовый порядок японского предложения — тема + дополнение + сказуемое. Глагол обычно стоит в конце. Частица は показывает тему (пишется ha, читается wa), を показывает прямой объект и читается o.","grammar":"私は日本語を勉強します。 Watashi wa nihongo o benkyou shimasu. 私は — тема «я», 日本語を — объект «японский язык», 勉強します — «изучаю». Частица が может выделять подлежащее, に указывает время/направление, で — место действия, の — принадлежность.","syntax":"日本語を勉強します = [что? 日本語を] [что делаю? 勉強します]. Не переносите русское «я изучаю японский» дословно: японский объект перед глаголом.","practice":"私は学生です。\nWatashi wa gakusei desu.\nЯ студент.\n\n図書館で本を読みます。\nToshokan de hon o yomimasu.\nЧитаю книгу в библиотеке.","pronunciation":"watashi wa · nihongo o · benkyou shimasu","quiz":[("Как произносится は как частица?","wa"),("Какая частица обозначает объект?","を, o"),("Где обычно глагол?","В конце предложения")],"links":[("Tae Kim: Grammar","https://guidetojapanese.org/learn/grammar"),("JLPT N5 grammar","https://jlptsensei.com/jlpt-n5-grammar-list/")]},
    {"id":"04","title":"です, ます и вопросы","kind":"grammar","goal":"Строить вежливые утверждения, отрицания и вопросы.","text":"です — вежливая связка после существительного или прилагательного. ます — вежливое окончание глагола. Вопрос часто получается добавлением か в конец; в письменной речи ставьте японский знак 。 или ？ по смыслу.","grammar":"学生です — являюсь студентом; 学生ではありません — не являюсь студентом; 学生ですか — студент? Для глагола: 食べます tabemasu — ем/буду есть; 食べません tabemasen — не ем.","syntax":"これは本です。 kore wa hon desu = [это] [книга] [есть]. Японский часто опускает подлежащее, если оно понятно из контекста.","practice":"これは何ですか。\nKore wa nan desu ka.\nЧто это?\n\n日本語を話しますか。\nNihongo o hanashimasu ka.\nВы говорите по-японски?","pronunciation":"desu · dewa arimasen · desu ka · tabemasu · tabemasen","quiz":[("Как сделать вопрос?","Добавить か в конец"),("Как сказать «не ем»?","食べません tabemasen")],"links":[("Tae Kim: Copula","https://guidetojapanese.org/learn/grammar/copula.html")]},
    {"id":"05","title":"Кандзи, числа и время","kind":"kanji","goal":"Узнавать первые кандзи и читать даты/время.","text":"Кандзи несут значение, а чтение меняется в составе слова. 一 ichi — один, 二 ni — два, 三 san — три, 日 hi/nichi — день/солнце, 月 tsuki/gatsu — луна/месяц. Не учите отдельный знак без примера слова.","grammar":"Число обычно ставится перед счётным словом. 今日は三月五日です。 Kyou wa sangatsu itsuka desu — Сегодня 5 марта. 月曜日 getsuyoubi — понедельник.","syntax":"Время и дата ставятся перед сказуемым: 7時に起きます shichi-ji ni okimasu — встаю в 7 часов. に указывает точное время.","practice":"一 二 三 四 五\n日本 — Япония (nihon)\n学生 — студент (gakusei)\n七時に起きます — встаю в семь","pronunciation":"ichi · ni · san · yon · go · nihon · gakusei · shichi-ji","quiz":[("Что означает 日?","день / солнце"),("Какая частица у точного времени?","に, ni"),("Как читать 日本?","nihon / nippon")],"links":[("Tofugu: Kanji","https://www.tofugu.com/japanese/kanji/"),("Kanji alive","https://app.kanjialive.com/")]},
    {"id":"06","title":"Глаголы и формы","kind":"grammar","goal":"Различать основу, вежливую форму и отрицание.","text":"Словарная форма 食べる taberu — есть. Вежливая форма 食べます tabemasu. Отрицание 食べません tabemasen. Прошедшее время 食べました tabemashita, отрицание 食べませんでした tabemasen deshita.","grammar":"Форма ます меняется по времени: ます настоящее/будущее, ません отрицание, ました прошедшее, ませんでした прошедшее отрицание. Это удобная безопасная форма для N5.","syntax":"В японском нет отдельного «я» в каждом предложении: 毎日勉強します Mainichi benkyou shimasu может значить «(я) учусь каждый день».","practice":"毎日日本語を勉強します。\nMainichi nihongo o benkyou shimasu.\nКаждый день изучаю японский.\n\n昨日映画を見ました。\nKinou eiga o mimashita.\nВчера смотрел фильм.","pronunciation":"taberu · tabemasu · tabemasen · tabemashita","quiz":[("Прошедшая вежливая форма?","ました"),("Отрицание настоящего?","ません"),("Что можно опустить?","Подлежащее, если понятно")],"links":[("Imabi: Japanese","https://imabi.org/lesson-1-introduction-to-japanese/"),("Tae Kim: Verbs","https://guidetojapanese.org/learn/grammar/verbs")]},
    {"id":"07","title":"Фразы и вежливость","kind":"phrases","goal":"Использовать устойчивые фразы без дословного перевода.","text":"Некоторые выражения лучше учить целиком. ありがとうございます arigatou gozaimasu — большое спасибо. すみません sumimasen — извините/простите/подскажите, пожалуйста. お願いします onegai shimasu — пожалуйста, прошу.","grammar":"よろしくお願いします yoroshiku onegai shimasu буквально трудно переводится; это вежливая формула «рассчитываю на сотрудничество». お疲れ様です otsukaresama desu — формула признания чужой работы.","syntax":"Приветствия зависят от ситуации: おはようございます утром, こんにちは днём, こんばんは вечером. Не нужно добавлять です после каждой фразы.","practice":"ありがとうございます — arigatou gozaimasu — спасибо\nすみません — sumimasen — извините\nお願いします — onegai shimasu — пожалуйста\nいただきます — itadakimasu — благодарность перед едой","pronunciation":"arigatou gozaimasu · sumimasen · onegai shimasu · itadakimasu","quiz":[("Что сказать перед едой?","いただきます itadakimasu"),("Утреннее приветствие?","おはようございます"),("Как вежливо привлечь внимание?","すみません")],"links":[("NHK Easy Japanese","https://www.nhk.or.jp/lesson/english/"),("Japan Foundation","https://www.jpf.go.jp/e/project/japanese/education/resource/")]},
    {"id":"08","title":"Синтаксис и итог N5","kind":"review","goal":"Собрать предложение, объяснить роль частиц и пройти итоговую проверку.","text":"Разбирайте предложение справа налево: найдите сказуемое, затем спросите «кто/что?», «что?», «где/когда?». Сначала определите частицы, затем чтение и форму слова. Не пытайтесь переводить каждый знак отдельно.","grammar":"Минимальный шаблон: [тема は] [время に] [место で] [объект を] [глагол]. Например: 私は毎日学校で日本語を勉強します。 Watashi wa mainichi gakkou de nihongo o benkyou shimasu.","syntax":"私 は / 毎日 / 学校 で / 日本語 を / 勉強します: я / каждый день / в школе / японский / изучаю. Подлежащее 私 можно убрать, если разговор уже о нём.","practice":"私は毎日学校で日本語を勉強します。\nWatashi wa mainichi gakkou de nihongo o benkyou shimasu.\nЯ каждый день изучаю японский в школе.","pronunciation":"watashi wa mainichi gakkou de nihongo o benkyou shimasu","quiz":[("Роль は?","Тема"),("Роль で?","Место действия / средство"),("Где сказуемое?","В конце"),("Переведите 日本語を話します。","Говорю по-японски")],"links":[("JLPT official","https://www.jlpt.jp/e/"),("JLPT N5 vocabulary","https://jlptsensei.com/jlpt-n5-vocabulary-list/")]},
    {"id":"09","title":"Прилагательные い и な","kind":"grammar","goal":"Описывать людей, предметы и впечатления в настоящем и прошлом.","text":"Прилагательные い заканчиваются на い: おいしい oishii — вкусный, あたらしい atarashii — новый. Прилагательные な требуют な перед существительным: しずかな町 shizuka na machi — тихий город.","grammar":"Отрицание い: おいしくない (невкусный), прошедшее おいしかった (был вкусным). Для な: しずかです, しずかではありません, しずかでした.","syntax":"この本はおもしろいです。 Kono hon wa omoshiroi desu — Эта книга интересная. Определение стоит перед существительным: あたらしい本.","practice":"日本語は難しいですが、おもしろいです。\nNihongo wa muzukashii desu ga, omoshiroi desu.\nЯпонский сложный, но интересный.","pronunciation":"oishii · omoshiroi · muzukashii · shizuka na","quiz":[("Как отрицать い-прилагательное?","Заменить い на くない"),("Что ставится перед существительным после な?","な"),("Переведите あたらしい本","новая книга")],"links":[("Tae Kim: Adjectives","https://guidetojapanese.org/learn/grammar/adjectives")]},
    {"id":"10","title":"Форма て и просьбы","kind":"grammar","goal":"Соединять действия и вежливо просить о чём-то.","text":"Форма て соединяет действия и используется в просьбах. Для N5 полезны готовые формы: 見てください mite kudasai — пожалуйста, посмотрите; 待ってください matte kudasai — подождите.","grammar":"Глагол + てください — вежливая просьба. Формы меняются по типу глагола, поэтому на первом этапе учите пример целиком: 読む → 読んで, 書く → 書いて, 食べる → 食べて.","syntax":"本を読んで、寝ます。 Hon o yonde, nemasu — Читаю книгу и ложусь спать. て связывает последовательность действий.","practice":"ちょっと待ってください。\nChotto matte kudasai.\nПожалуйста, подождите немного.\n\nここに名前を書いてください。\nKoko ni namae o kaite kudasai.\nНапишите имя здесь.","pronunciation":"mite kudasai · matte kudasai · yonde nemasu","quiz":[("Как попросить посмотреть?","見てください mite kudasai"),("Что делает て?","Соединяет действия / образует просьбу"),("Форма て от 読む?","読んで")],"links":[("Tae Kim: Te-form","https://guidetojapanese.org/learn/grammar/teform.html")]},
    {"id":"11","title":"Место, направление и счётчики","kind":"vocabulary","goal":"Говорить, где находится предмет и куда вы идёте.","text":"ここ koko — здесь, そこ soko — там у собеседника, あそこ asoko — вон там. 右 migi — право, 左 hidari — лево, 上 ue — сверху, 下 shita — снизу.","grammar":"あります используется для неодушевлённых предметов, います — для людей и животных. Место + に + предметがあります: 机の上に本があります.","syntax":"駅はどこですか。 Eki wa doko desu ka — Где станция? 駅に行きます — Иду на станцию. Для количества учите счётчик вместе с числом: 一人 hitori, 二人 futari.","practice":"机の上に本があります。\nTsukue no ue ni hon ga arimasu.\nНа столе есть книга.\n\n猫がいます。\nNeko ga imasu.\nЕсть кошка.","pronunciation":"koko · soko · doko · arimasu · imasu · hitori · futari","quiz":[("Что используем для человека?","います"),("Где предмет в шаблоне?","Место に предмет が あります"),("Как сказать «где»?","どこ doko")],"links":[("Tae Kim: Locations","https://guidetojapanese.org/learn/grammar/verbs.html")]},
    {"id":"12","title":"Аудирование и повторение N5","kind":"review","goal":"Научиться извлекать смысл из короткой реплики без перевода каждого слова.","text":"Сначала слушайте или читайте фразу целиком и угадывайте ситуацию. Затем найдите сказуемое, частицы и ключевые слова. Ромадзи используйте как временную опору, но постепенно переходите к чтению каны.","grammar":"Повторите шаблоны: これは何ですか, ～があります, ～に行きます, ～てください, ～たいです. Для желания используется форма たい: 日本へ行きたいです — хочу поехать в Японию.","syntax":"Разбор: 明日 / 友達と / 映画を / 見たいです — завтра / с другом / фильм / хочу посмотреть. Сначала время, затем участник, объект и сказуемое.","practice":"明日友達と映画を見たいです。\nAshita tomodachi to eiga o mitai desu.\nЗавтра хочу посмотреть фильм с другом.\n\nПовторите вслух 3 раза, затем закройте ромадзи и прочитайте кана.","pronunciation":"ashita tomodachi to eiga o mitai desu","quiz":[("Как выразить желание?","Глагольная основа + たいです"),("Что сделать первым при аудировании?","Понять ситуацию и общий смысл"),("Переведите 友達と","с другом")],"links":[("NHK Easy Japanese","https://www.nhk.or.jp/lesson/english/"),("JLPT official sample questions","https://www.jlpt.jp/e/samples/sampleindex.html")]},
]


def _kana_lesson(id: str, title: str, goal: str, text: str, table: list, quiz: list,
                 links: list, pronunciation: str) -> dict:
    return {"id": id, "title": title, "kind": "kana", "goal": goal, "text": text,
            "grammar": "Каждый знак — одна мора (ритмический шаг). Хирагана и катакана обозначают одни и те же звуки.",
            "syntax": "Знаки пишутся в одинаковом порядке слева направо, сверху вниз; пробелов между словами нет.",
            "practice": kana.practice_table(table), "pronunciation": pronunciation,
            "quiz": quiz, "links": links}


